from datetime import datetime


def parse_event(line: str) -> dict:
    timestamp, level, rest = line.split(' ', 2)
    service, message = rest.split(':', 1)
    return {'timestamp': datetime.fromisoformat(timestamp), 'level': level, 'service': service, 'message': message.strip()}

