import json


def ready_components(text: str, format_name: str) -> list[str]:
    if format_name == 'jsonl':
        rows = [json.loads(line) for line in text.splitlines() if line.strip()]
    else:
        rows = []
    return [f"{row['component']}=={row['version']}" for row in rows if row.get('status') == 'ready']

