import unittest
from release_guard.config import parse_config

class T(unittest.TestCase):
    def test_comments_whitespace_equals_and_duplicate(self):
        text = '# note\n A = first \nURL=https://x.test?a=1\nA=last\n\n'
        self.assertEqual(parse_config(text), {'A': 'last', 'URL': 'https://x.test?a=1'})
    def test_malformed_line_number(self):
        with self.assertRaisesRegex(ValueError, 'line 2'):
            parse_config('OK=1\nbroken')

