import unittest
from release_guard.redact import redact_secrets

class T(unittest.TestCase):
    def test_assignment_and_bearer(self):
        raw = 'api_key=alpha TOKEN : beta PASSWORD = gamma Authorization: Bearer delta user=ok'
        cleaned = redact_secrets(raw)
        for secret in ('alpha','beta','gamma','delta'):
            self.assertNotIn(secret, cleaned)
        self.assertIn('user=ok', cleaned)
        self.assertEqual(cleaned.count('<redacted>'), 4)

