import unittest
from release_guard.events import parse_event
from release_guard.report import build_report

class T(unittest.TestCase):
    def test_report(self):
        rows = [parse_event('2026-09-01T10:00:00Z info api: start'), parse_event('2026-09-01T10:02:00+00:00 ERROR worker: failed'), parse_event('2026-09-01T10:01:00Z INFO api: ready')]
        self.assertEqual(build_report(rows), {'total': 3, 'by_level': {'ERROR': 1, 'INFO': 2}, 'by_service': {'api': 2, 'worker': 1}, 'latest': '2026-09-01T10:02:00+00:00'})
    def test_bad_event(self):
        with self.assertRaises(ValueError): parse_event('not an event')

