import hashlib
import unittest
from release_guard.diagnostics import checksum_lines, retention_days

class T(unittest.TestCase):
    def test_checksum(self): self.assertEqual(checksum_lines(['a','b']), hashlib.sha256(b'a\nb').hexdigest())
    def test_retention(self):
        self.assertEqual(retention_days('30d'), 30)
        self.assertEqual(retention_days('25h'), 2)
        for bad in ('-1d','4w','x'):
            with self.assertRaises(ValueError): retention_days(bad)
